const urlOriginal = $('Rotear Tipo').item.json.url_anexo;
const semConteudo = transcricao.length < 2;
const textoFinal = semConteudo
  ? '[Audio recebido do cliente, mas nao foi possivel identificar nenhum conteudo compreensivel na transcricao -- pode ser ruido, silencio ou audio muito curto. Peca ao cliente para repetir o audio ou escrever a mensagem em texto. Nunca invente o que o cliente pode ter dito.]'
  : `[Áudio transcrito do cliente]: "${transcricao}"`;
