return [{ json: {
  tipo_processado: 'audio',
  texto_final: '[Falha tecnica ao processar o audio enviado pelo cliente -- nao foi possivel baixar ou transcrever. Peca ao cliente para tentar reenviar o audio ou escrever a mensagem em texto. Nunca invente o que o audio poderia conter.]',
  midia_url: urlOriginal,
  transcricao: null,
  interpretacao: { erro_processamento: true },
  confianca: null,
} }];

let extraida;
try {
  let raw = ($json.content || '').trim();
  raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
  extraida = JSON.parse(raw);
} catch (e) {
  extraida = {
    tipo_imagem: 'outro',
    confianca: 0,
    produto_nome: null,
    produto_especie: null,
    produto_apresentacao: null,
    receita_itens: [],
    texto_ilegivel_ou_ambiguo: true,
    observacoes: 'Falha ao interpretar resposta do modelo de visao.',
  };
}

const tipoImagem = extraida.tipo_imagem === 'receita_veterinaria' || extraida.tipo_imagem === 'produto' ? extraida.tipo_imagem : 'outro';
const confianca = typeof extraida.confianca === 'number' ? extraida.confianca : 0;
const produtoNome = typeof extraida.produto_nome === 'string' && extraida.produto_nome.trim() ? extraida.produto_nome.trim() : null;
const produtoEspecie = extraida.produto_especie === 'cachorro' || extraida.produto_especie === 'gato' ? extraida.produto_especie : null;
const produtoApresentacao = typeof extraida.produto_apresentacao === 'string' && extraida.produto_apresentacao.trim() ? extraida.produto_apresentacao.trim() : null;
const receitaItens = Array.isArray(extraida.receita_itens) ? extraida.receita_itens.filter(x => typeof x === 'string' && x.trim()) : [];
const ilegivel = !!extraida.texto_ilegivel_ou_ambiguo;
const observacoes = extraida.observacoes || '';

const CONFIANCA_MINIMA = 0.6;
const produtoConfirmado = tipoImagem === 'produto' && !!produtoNome && confianca >= CONFIANCA_MINIMA && !ilegivel;
const receitaConfirmada = tipoImagem === 'receita_veterinaria' && receitaItens.length > 0 && confianca >= CONFIANCA_MINIMA && !ilegivel;

return [{ json: {
  tipo_imagem: tipoImagem,
  confianca,
  produto_nome: produtoNome,
  produto_especie: produtoEspecie,
  produto_apresentacao: produtoApresentacao,
  receita_itens: receitaItens,
  texto_ilegivel_ou_ambiguo: ilegivel,
  observacoes,
  produto_confirmado: produtoConfirmado,
  receita_confirmada: receitaConfirmada,
} }];

const d = $json;
const urlOriginal = $('Rotear Tipo').item.json.url_anexo;
const legenda = $('Rotear Tipo').item.json.mensagem || '';

let textoFinal;
let interpretacaoParaSalvar = {
  tipo_imagem: d.tipo_imagem,
  produto_nome: d.produto_nome,
  produto_especie: d.produto_especie,
  produto_apresentacao: d.produto_apresentacao,
  receita_itens: d.receita_itens,
  texto_ilegivel_ou_ambiguo: d.texto_ilegivel_ou_ambiguo,
  observacoes: d.observacoes,
  confianca: d.confianca,
};

if (d.tipo_imagem === 'produto' && d.produto_confirmado) {
  const detalhes = [d.produto_especie ? `especie: ${d.produto_especie}` : null, d.produto_apresentacao ? `apresentacao: ${d.produto_apresentacao}` : null].filter(Boolean).join(', ');
  textoFinal = `[Imagem enviada pelo cliente: PRODUTO] Produto identificado: ${d.produto_nome}${detalhes ? ' (' + detalhes + ')' : ''}. Confianca: ${d.confianca}. Chame buscar_produto UMA UNICA VEZ usando como consulta APENAS o nome do produto ("${d.produto_nome}") -- nunca inclua especie/apresentacao/peso na string de busca, e nunca busque cada palavra da imagem separadamente. Espécie e apresentacao servem so pra voce confirmar ou desambiguar DEPOIS, entre os resultados que a busca retornar -- nunca pra compor a query. Responda diretamente se temos ou nao esse produto, sem devolver uma lista longa de produtos nao relacionados.`;
  if (legenda) textoFinal += ` Legenda do cliente: "${legenda}"`;
  interpretacaoParaSalvar.fonte = 'identificado_na_imagem';
} else if (d.tipo_imagem === 'receita_veterinaria' && d.receita_confirmada) {
  textoFinal = `[Imagem enviada pelo cliente: RECEITA VETERINARIA] Itens identificados com leitura clara: ${d.receita_itens.join(', ')}. IMPORTANTE: isso veio de uma receita veterinaria -- ajude somente na parte comercial (buscar esses itens no catalogo), nunca interprete dosagem nem faca recomendacao medica. Deixe claro ao cliente que a leitura foi feita a partir da receita enviada e confirme os itens com ele antes de agir.`;
  interpretacaoParaSalvar.fonte = 'identificado_na_receita';
} else if (d.tipo_imagem === 'outro') {
  textoFinal = `[Imagem enviada pelo cliente] Nao foi possivel identificar um produto ou receita com clareza nesta imagem. Descricao: ${d.observacoes || '(sem descricao)'}. Pergunte ao cliente de forma natural e acolhedora o que ele precisa -- trate isso como uma pergunta de esclarecimento normal, nunca como um erro ou bloqueio.`;
  interpretacaoParaSalvar.fonte = 'nao_identificado';
} else {
  const eReceita = d.tipo_imagem === 'receita_veterinaria';
  textoFinal = `[Imagem enviada pelo cliente: ${eReceita ? 'POSSIVEL RECEITA' : 'PRODUTO'} -- NAO FOI POSSIVEL CONFIRMAR PELA IMAGEM] Nao foi possivel identificar com confianca suficiente o que esta nesta imagem (motivo: ${d.texto_ilegivel_ou_ambiguo ? 'imagem pouco nitida ou informacao ilegivel' : 'informacao insuficiente na imagem'}). Voce NAO pode adivinhar, inferir ou completar qual produto ou medicamento e${eReceita ? ' a partir da receita' : ''} -- vale mesmo que o cliente insista ou diga que 'e obvio'. Isso NAO significa que a conversa trava: de forma natural e acolhedora (nunca como um erro tecnico), ofereca as duas alternativas juntas na MESMA mensagem -- pedir uma foto mais nitida, E perguntar diretamente o nome do produto/medicamento que o cliente precisa. Se o cliente informar o nome (em texto ou audio, agora ou depois), trate isso como um PEDIDO EXPLICITO DELE -- nunca diga que a imagem/receita confirmou isso, diga algo como 'voce me informou que precisa de X, vou verificar' -- e prossiga normalmente com buscar_produto para esse nome. Se o produto informado nao existir, a apresentacao nao bater com nenhuma variante, ou houver ambiguidade entre variantes, peca esclarecimento -- nunca escolha sozinho.`;
  interpretacaoParaSalvar.produto_nome = null;
  interpretacaoParaSalvar.receita_itens = [];
  interpretacaoParaSalvar.fonte = eReceita ? 'receita_nao_confirmada_aguardando_cliente' : 'produto_nao_confirmado_aguardando_cliente';
}

return [{ json: {
  tipo_processado: 'image',
  texto_final: textoFinal,
  midia_url: urlOriginal,
  transcricao: null,
  interpretacao: interpretacaoParaSalvar,
  confianca: d.confianca,
} }];

